+afterEach(async () => {
+  const current = root;
+  root = null;
+  if (current) await act(async () => current.unmount());
+});
+
+const isolated = () => {
+  const s = useViewerStore.getState().isolatedEntities;
+  return s ? [...s].sort((a, b) => a - b) : null;
