+      mkdirSync(join(root, 'nested'));
+      writeFileSync(join(root, 'nested', 'Ok.tsx'), 'export const x = 1;');
+      const out = [];
+      const errors = [];
+      walk(root, out, errors);
+      assert.equal(errors.length, 0);
+      assert.equal(out.length, 1);
+    } finally {
